/bin/zsh -lc "<BUNDLED_PYTHON> - <<'PY'
import csv,json,itertools,zipfile
from pathlib import Path
from datetime import date
from openpyxl import load_workbook
I=Path('inputs'); O=Path('output')
def readcsv(p): return list(csv.DictReader((I/p).open(encoding='utf-8-sig',newline='')))
def b(v): return v.lower()=='true'
roster,avail,hr=readcsv('01_roster.csv'),readcsv('02_availability.csv'),readcsv('03_hr_changes.csv')
inv,cred,pay,fac=readcsv('04_invoices.csv'),readcsv('05_credits.csv'),readcsv('06_payments.csv'),readcsv('07_session_options.csv')
terms=json.loads((I/'08_supplier_terms.json').read_text()); cons=json.loads((I/'09_approved_constraints.json').read_text())
assert sum(map(len,[roster,avail,hr,inv,cred,pay,fac]))==263
expected={}; selected={}
for kind,rows,idcol in [('invoice',inv,'invoice_id'),('credit',cred,'credit_id'),('payment',pay,'payment_id')]:
    groups={}
    for r in rows: groups.setdefault(r[idcol],[]).append(r)
    selected[kind]=[]
    for bid,g in groups.items():
        posted=[r for r in g if r['status']"'!='"'draft']; hi=max([int(r['revision']) for r in posted],default=-1)
        top=[r for r in posted if int(r['revision'])==hi]; payloads={}
        for r in top: payloads.setdefault((r['revision'],r['status'],r['amount_krw'],r['invoice_id']),[]).append(r)
        d={r['row_id']:('draft' if r['status']=='draft' else 'superseded') for r in g if r['status']=='draft' or int(r['revision'])<hi}
        for same in payloads.values():
            same.sort(key=lambda x:x['row_id']); rep=same[0]; selected[kind].append(rep)
            d[rep['row_id']]={'posted':'active','void':'void','reversed':'reversed'}[rep['status']]
            for x in same[1:]: d[x['row_id']]='duplicate'
        for r in g:
            disp=d[r['row_id']]; expected[r['row_id']]={'kind':kind,'business_id':r[idcol],'source_id':r['source_id'],'disposition':disp,'recognized_krw':int(r['amount_krw']) if disp=='active' else 0}
records=list(csv.DictReader((O/'records.csv').open(encoding='utf-8',newline='')))
assert len(records)==101 and set(x['row_id'] for x in records)==set(expected)
for r in records:
    e=expected[r['row_id']]
    for k,v in e.items(): assert str(v)==r[k]
balances=list(csv.DictReader((O/'balances.csv').open(encoding='utf-8',newline='')))
assert len(balances)==36
for n in range(1,37):
    iid=f'INV{n:02d}'; x=next(r for r in balances if r['invoice_id']==iid)
    ir=next(r for r in selected['invoice'] if r['invoice_id']==iid)
    cr=[r for r in selected['credit'] if r['invoice_id']==iid]; pr=[r for r in selected['payment'] if r['invoice_id']==iid]
    amount=lambda r:int(r['amount_krw']) if r['status']=='posted' else 0
    assert x['invoice_row_id']==ir['row_id'] and int(x['gross_krw'])==amount(ir)
    assert int(x['credit_krw'])==sum(map(amount,cr)) and int(x['paid_krw'])==sum(map(amount,pr))
    assert int(x['balance_krw'])==int(x['gross_krw'])-int(x['credit_krw'])-int(x['paid_krw'])>=0
    assert set(filter(None,x['credit_row_ids'].split(';')))=={r['row_id'] for r in cr}
    assert set(filter(None,x['payment_row_ids'].split(';')))=={r['row_id'] for r in pr}
reserve=sum(int(x['balance_krw']) for x in balances); assert reserve==787600
plan=json.loads((O/'plan.json').read_text()); s=plan['summary']
keys='total_cash_cap_krw historical_outstanding_krw launch_budget_krw vendor_id vendor_fixed_krw vendor_per_person_krw room_cost_krw launch_cost_krw cash_remaining_krw assigned_count mandatory_count optional_count approval_status preparation_dates'.split()
assert list(s)==keys and s['launch_budget_krw']==int(cons['total_cash_cap_krw'])-reserve==965000
assert plan.keys()=={'summary','assignments','sessions','evidence'} and len(plan['evidence'])==12
R={x['person_id']:x for x in roster}; Av={x['person_id']:x for x in avail}; approved={}
for x in hr:
    if x['approval']=='approved': approved.setdefault(x['person_id'],[]).append(x)
final={}
for pid,r in R.items():
    x={'tier':r['tier'],'active':b(r['active']),'access_required':b(r['access_required']),'allowed_sessions':Av[pid]['allowed_sessions'].split(';')}
    for h in approved.get(pid,[]): x[h['field']]=b(h['value']) if h['field'] in ('active','access_required') else h['value'].split(';') if h['field']=='allowed_sessions' else h['value']
    if x['active']:final[pid]=x
A={x['person_id']:x for x in plan['assignments']}; assert len(A)==72 and set(A)==set(final)
for pid,a in A.items():
    f=final[pid]; assert (a['tier'],a['access_required'],a['allowed_sessions'])==(f['tier'],f['access_required'],f['allowed_sessions'])
    src={R[pid]['row_id'],Av[pid]['row_id'],*(h['row_id'] for h in approved.get(pid,[]))}; assert set(a['source_row_ids'])==src
    assert not ({h['row_id'] for h in hr if h['person_id']==pid and h['approval']"'!='"'approved'} & set(a['source_row_ids']))
F={x['session_id']:x for x in fac}; V=next(v for v in terms['vendors'] if v['vendor_id']==s['vendor_id']); assert V['approval']=='approved'
counts={}
for q in plan['sessions']:
    f=F[q['session_id']]; d=date.fromisoformat(f['date']); cap=min(int(f['capacity']),V['capacity_per_session'])
    assert f['approval']=='approved' and q['source_id']==f['source_id'] and q['capacity']==cap and q['accessible']==b(f['accessible'])
    assert cons['window_start']<=f['date']<=cons['window_end'] and d.weekday()<5 and f['date'] not in cons['company_holidays']
    counts[q['session_id']]=0
assert len(counts)==4 and len({F[x]['date'] for x in counts})==4
for a in A.values():
    if a['state']=='assigned':
        assert a['session_id'] in counts and a['session_id'] in a['allowed_sessions']
        q=next(x for x in plan['sessions'] if x['session_id']==a['session_id']); assert not a['access_required'] or q['accessible']; counts[a['session_id']]+=1
    else: assert a['state']=='waitlist' and a['session_id']==''
assert all(counts[x]>0 for x in counts)
assert all(counts[q['session_id']]==q['attendees']<=q['capacity'] for q in plan['sessions'])
assigned=[a for a in A.values() if a['state']=='assigned']; assert len(assigned)==66
assert sum(a['tier']=='mandatory' for a in assigned)==60 and sum(a['tier']=='optional' for a in assigned)==6
room=sum(q['room_cost_krw'] for q in plan['sessions']); assert room==260000 and s['vendor_id']=='CEDAR'
assert s['launch_cost_krw']==s['vendor_fixed_krw']+s['vendor_per_person_krw']*66+room==962000 and s['cash_remaining_krw']==3000
# Offer coverage bound under the unique mandatory-feasible session set.
assert final['P020']['allowed_sessions']==['S5'] and final['P025']['allowed_sessions']==['S3'] and final['P060']['allowed_sessions']==['S6']
cohort=[f'P{i:03d}' for i in (*range(1,16),*range(31,46))]
assert all(final[p]['tier']=='mandatory' for p in cohort)
s1=[p for p in cohort if 'S1' in final[p]['allowed_sessions']]; assert s1==['P005','P010','P015','P035','P040']
assert len(cohort)>int(F['S5']['capacity'])+len(s1)
max_opt={v['vendor_id']:(s['launch_budget_krw']-room-int(v['fixed_krw']))//int(v['per_person_krw'])-60 for v in terms['vendors'] if v['approval']=='approved'}
assert max_opt=={'CEDAR':6,'LYRA':3,'ORCHID':4} and max_opt[s['vendor_id']]==s['optional_count']
# Workbook content, row counts, format and ZIP integrity.
with zipfile.ZipFile(O/'operations.xlsx') as z: assert z.testzip() is None
wb=load_workbook(O/'operations.xlsx',data_only=True); assert wb.sheetnames==['대사기록','송장잔액','배정','일정','예산','근거']
expected_tables=[('대사기록',records),('송장잔액',balances),('배정',plan['assignments']),('일정',plan['sessions']),('예산',[{'key':k,'value':';'.join(v) if isinstance(v,list) else v} for k,v in s.items()]),('근거',plan['evidence'])]
for name,data in expected_tables:
    ws=wb[name]; h=list(data[0]); vals=list(ws.values); assert list(vals[0])==h and len(vals)==len(data)+1 and ws.freeze_panes=='A2'
    for row,src in zip(vals[1:],data):
        for got,key in zip(row,h):
            exp=src[key]
            if isinstance(exp,list): exp=';'.join(exp)
            if isinstance(exp,str) and (key.endswith('_krw') or key in ('attendees','capacity')) and exp.isdigit(): exp=int(exp)
            if got is None:got=''
            assert got==exp,(name,key,got,exp)
    assert not any(c.data_type=='f' for line in ws.iter_rows() for c in line)
assert '원' in wb['예산']['B2'].number_format and '원' in wb['대사기록']['E2'].number_format
wb.close()
print(json.dumps({'independent_audit':'passed','tabular_source_rows':263,'ledger_rows':len(records),'invoices':len(balances),'reserve_krw':reserve,'budget_krw':s['launch_budget_krw'],'vendor':s['vendor_id'],'assigned_count':len(assigned),'mandatory_count':60,'optional_count':6,'sessions':list(counts),'launch_cost_krw':s['launch_cost_krw'],'cash_remaining_krw':s['cash_remaining_krw'],'optional_waitlist':[a['person_id'] for a in A.values() if a['state']=='waitlist']},ensure_ascii=False,indent=2))
PY"
